// Writes what prost-build (with prost-reflect-build's attributes) writes
// for three .proto files: of packages fixture.shapes and wrapped, and one
// with none. No
// prost dependency: rust-analyzer outlines the files whether or not their
// derives resolve, and the layer reads nothing else.
use std::{env, fs, path::Path};

const SHAPES: &str = r#"// This file is @generated by prost-build.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Shape {
    #[prost(string, tag = "1")]
    pub name: ::prost::alloc::string::String,
    #[prost(oneof = "shape::Kind", tags = "2")]
    pub kind: ::core::option::Option<shape::Kind>,
}
/// Nested message and enum types in `Shape`.
pub mod shape {
    #[derive(
        Clone,
        Copy,
        Debug,
        PartialEq,
        Eq,
        Hash,
        PartialOrd,
        Ord,
        ::prost::Enumeration
    )]
    #[repr(i32)]
    pub enum Unit {
        Mm = 0,
        In = 1,
    }
    impl Unit {
        pub fn as_str_name(&self) -> &'static str {
            match self {
                Self::Mm => "MM",
                Self::In => "IN",
            }
        }
    }
    #[derive(Clone, PartialEq, ::prost::Oneof)]
    pub enum Kind {
        #[prost(int32, tag = "2")]
        Side(i32),
    }
}
#[derive(::prost_reflect::ReflectMessage)]
#[prost_reflect(message_name = "fixture.shapes.Stated")]
#[prost_reflect(message_name = "Stated")]
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Stated {}
#[derive(::prost_reflect::ReflectMessage)]
#[prost_reflect(message_name = "other.Misnamed")]
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Misnamed {}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Named {}
impl ::prost::Name for Named {
    const NAME: &'static str = "Named";
    const PACKAGE: &'static str = "fixture.shapes";
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Renamed {}
impl ::prost::Name for Renamed {
    const NAME: &'static str = "Renamed";
    const PACKAGE: &'static str = "other";
}
"#;

const LOOSE: &str = "// This file is @generated by prost-build.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Loose {}
";

const WRAPPED: &str = "// This file is @generated by prost-build.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Via {}
";

fn main() {
    let out = env::var("OUT_DIR").unwrap();
    fs::write(Path::new(&out).join("wrapped.rs"), WRAPPED).unwrap();
    fs::write(Path::new(&out).join("fixture.shapes.rs"), SHAPES).unwrap();
    fs::write(Path::new(&out).join("_.rs"), LOOSE).unwrap();
}
